import type { WixDataAsyncPatchByFilterOptions } from './types'

/**
 * Options builder for async patch-by-filter operations.
 *
 * Use this builder to configure async patch behavior such as hooks suppression.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataAsyncPatchByFilterOptionsBuilder {
  /**
   * Sets whether to suppress async patch hooks.
   *
   * When `true`, the async patch runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataAsyncPatchByFilterOptionsBuilder
  /**
   * Sets whether to include draft items when patching items asynchronously.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataAsyncPatchByFilterOptionsBuilder
  /**
   * Builds the async patch by filter options object.
   */
  build(): WixDataAsyncPatchByFilterOptions
}

class WixDataAsyncPatchByFilterOptionsBuilderImpl
  implements WixDataAsyncPatchByFilterOptionsBuilder
{
  constructor(
    private readonly options: WixDataAsyncPatchByFilterOptions = {}
  ) {}

  withSuppressHooks(value: boolean): WixDataAsyncPatchByFilterOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataAsyncPatchByFilterOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  build(): WixDataAsyncPatchByFilterOptions {
    return {
      ...this.options,
    }
  }

  private copy(
    options: WixDataAsyncPatchByFilterOptions
  ): WixDataAsyncPatchByFilterOptionsBuilder {
    return new WixDataAsyncPatchByFilterOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new async patch-by-filter options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create an async patch-by-filter options builder"
 * import { items, AsyncPatchByFilterOptionsBuilder } from '@wix/data'
 *
 * const options = AsyncPatchByFilterOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .build()
 *
 * const job = await items.asyncPatchByFilter(
 *   'myCollection',
 *   { archived: false },
 *   [],
 *   options
 * )
 * ```
 */
export const AsyncPatchByFilterOptionsBuilder: () => WixDataAsyncPatchByFilterOptionsBuilder =
  () => new WixDataAsyncPatchByFilterOptionsBuilderImpl()
